class ResolvedDataset(BaseModel):
    """
    What the gateway sends a service in place of a bare UUID: the dataset metadata
    plus a signed READ url. TTL MUST exceed max queue wait + max_job_duration, or a
    long-queued job dies on an expired URL (CONTRACT-CHANGES D15).

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    dataset_id: UUID
    name: str
    dataset_format: DatasetFormat
    dataset_role: DatasetRole | None
    size_bytes: int = Field(..., ge=0)
    crs: Crs
    bbox: Bbox | None
    signed_url: str = Field(..., description='Treat as a credential. Never log.')
    signed_url_expires_at: Timestamp


class OutputUploadUrl(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    output_format: DatasetFormat
    storage_key: str
    url: str
    expires_at: Timestamp


class InternalJobRequest(BaseModel):
    """
    Gateway -> Service. `input_datasets` maps the SAME keys as the job's
    input_dataset_ids, with UUIDs resolved to ResolvedDataset.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    job_id: UUID
    service: ServiceName
    model: str | None
    input_datasets: dict[str, ResolvedDataset]
    params: (
        BuildingExtractionParams
        | PointCloudClassificationParams
        | LandcoverDetectionParams
        | Reconstruction3dParams
        | ConverterParams
    )
    output_prefix: str = Field(
        ...,
        description='Storage prefix the service MUST write under. The PDF specified signed READ\nurls for inputs but never said how a service writes its OUTPUT bytes at all\n(CONTRACT-CHANGES A3).\n',
    )
    output_upload_urls: list[OutputUploadUrl] = Field(
        ..., description='Presigned PUT, one per requested output format.'
    )
    callback_url: str
    max_job_duration_seconds: int = Field(
        ...,
        description="After this, the gateway's reaper marks the job failed/JOB_TIMEOUT and\nrefunds. Without it a crashed worker strands a paid job forever\n(CONTRACT-CHANGES B4).\n",
        ge=1,
    )
    heartbeat_interval_seconds: int = Field(
        ...,
        description='The service MUST emit a processing callback at least this often while\nworking (see docs/job-lifecycle.md). Lets the reaper distinguish a slow\njob from a dead worker long before max_job_duration_seconds expires.\n',
        ge=1,
    )


