class ServiceCapabilities(BaseModel):
    """
    Lets the gateway/UI discover what a service supports instead of hardcoding it.
    For the converter this carries the source->target conversion matrix, so the UI
    never offers an impossible conversion the user would be billed for.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    service: ServiceName
    version: str
    contract_version: str
    models: list[str]
    output_formats: list[DatasetFormat]
    max_input_size_bytes: int
    conversion_matrix: dict[str, list[DatasetFormat]] | None = Field(
        None,
        description='converter only. source dataset_format -> allowed target formats.',
    )


